import { writeFileSync } from 'node:fs';

const cases = [];
const add = (name, a, b = '5') => cases.push({ name, argv: ['--a', a, '--b', b] });
const C = (n) => String.fromCharCode(n);

// ---- 1. Every ASCII byte 0x01..0x7f as the SOLE --a value -----------------
for (let n = 1; n <= 0x7f; n += 1) add(`sole-0x${n.toString(16).padStart(2, '0')}`, C(n));

// ---- 2. Every ASCII byte 0x01..0x7f embedded among other characters -------
for (let n = 1; n <= 0x7f; n += 1) {
  add(`embed-0x${n.toString(16).padStart(2, '0')}`, `A${C(n)}z9${C(n)}~`);
}
writeFileSync('/tmp/cases-br1.json', JSON.stringify(cases, null, 1));
console.log(cases.length);
EOF
